DO $$ DECLARE
  sid UUID := '00000000-0000-0000-0000-000000000001';
  caw_id UUID;
BEGIN
  SELECT id INTO caw_id FROM subjects WHERE code='CAW' AND deleted_at IS NULL LIMIT 1;
  DELETE FROM quiz_responses WHERE question_id IN (SELECT id FROM questions WHERE subject_id=caw_id);
  DELETE FROM quiz_questions WHERE question_id IN (SELECT id FROM questions WHERE subject_id=caw_id);
  DELETE FROM questions WHERE subject_id=caw_id AND deleted_at IS NULL;
END $$;
