  INSERT INTO subjects (id, name, code, school_id) SELECT gen_random_uuid(), 'Computer Awareness', 'CAW', sid WHERE NOT EXISTS (SELECT 1 FROM subjects WHERE code='CAW' AND school_id=sid AND deleted_at IS NULL);
  INSERT INTO questions (school_id, subject_id, question_type, question_text, options, answer, marks, difficulty, chapters, tags, is_active) VALUES
  (sid, caw_id, 'mcq', 'The word computer has been derived from which of the following languages?', '[{"key": "A", "value": "Greek", "correct": false}, {"key": "B", "value": "English", "correct": false}, {"key": "C", "value": "French", "correct": false}, {"key": "D", "value": "Latin", "correct": true}]', 'D', 2, 'easy', '["Introduction to Computer"]', '["history", "terminology"]', true),
  (sid, caw_id, 'mcq', 'Input, output and processing devices grouped together represent a(n):', '[{"key": "A", "value": "mobile device", "correct": false}, {"key": "B", "value": "information processing cycle", "correct": false}, {"key": "C", "value": "circuit board", "correct": false}, {"key": "D", "value": "computer system", "correct": true}]', 'D', 2, 'easy', '["Introduction to Computer"]', '["fundamentals"]', true),
  (sid, caw_id, 'mcq', 'Which of the following is the correct order of the four major functions of a computer?', '[{"key": "A", "value": "Process, Output, Input, Storage", "correct": false}, {"key": "B", "value": "Input, Output, Process, Storage", "correct": false}, {"key": "C", "value": "Process, Storage, Input, Output", "correct": false}, {"key": "D", "value": "Input, Process, Output, Storage", "correct": true}]', 'D', 2, 'medium', '["Introduction to Computer"]', '["fundamentals", "process_cycle"]', true),
  (sid, caw_id, 'mcq', 'Collecting raw data and converting it into meaningful information is called:', '[{"key": "A", "value": "processing", "correct": true}, {"key": "B", "value": "compiling", "correct": false}, {"key": "C", "value": "importing", "correct": false}, {"key": "D", "value": "exporting", "correct": false}, {"key": "E", "value": "None of these", "correct": false}]', 'A', 2, 'easy', '["Introduction to Computer"]', '["fundamentals", "data_processing"]', true),
  (sid, caw_id, 'mcq', 'Which of the following is a function that a computer CANNOT perform?', '[{"key": "A", "value": "input", "correct": false}, {"key": "B", "value": "output", "correct": false}, {"key": "C", "value": "thinking", "correct": true}, {"key": "D", "value": "processing", "correct": false}]', 'C', 2, 'easy', '["Introduction to Computer"]', '["limitations"]', true),
  (sid, caw_id, 'mcq', 'A collection of raw, unprocessed items is referred to as:', '[{"key": "A", "value": "information", "correct": false}, {"key": "B", "value": "data", "correct": true}, {"key": "C", "value": "memory", "correct": false}, {"key": "D", "value": "reports", "correct": false}, {"key": "E", "value": "None of these", "correct": false}]', 'B', 2, 'easy', '["Introduction to Computer"]', '["fundamentals", "data"]', true),
  (sid, caw_id, 'mcq', 'Data that has been organized, structured, and presented in a meaningful fashion is known as:', '[{"key": "A", "value": "A process", "correct": false}, {"key": "B", "value": "Software", "correct": false}, {"key": "C", "value": "Storage", "correct": false}, {"key": "D", "value": "Information", "correct": true}, {"key": "E", "value": "Data", "correct": false}]', 'D', 2, 'easy', '["Introduction to Computer"]', '["fundamentals", "information"]', true),
  (sid, caw_id, 'mcq', 'The earliest historical calculating device is which of the following?', '[{"key": "A", "value": "calculator", "correct": false}, {"key": "B", "value": "abacus", "correct": true}, {"key": "C", "value": "difference engine", "correct": false}, {"key": "D", "value": "analytical engine", "correct": false}, {"key": "E", "value": "None of the above", "correct": false}]', 'B', 2, 'easy', '["Introduction to Computer"]', '["history", "calculators"]', true),
  (sid, caw_id, 'mcq', 'Which mathematical operations can the traditional abacus perform?', '[{"key": "A", "value": "addition", "correct": false}, {"key": "B", "value": "subtraction", "correct": false}, {"key": "C", "value": "multiplication", "correct": false}, {"key": "D", "value": "Both addition and subtraction", "correct": true}]', 'D', 2, 'medium', '["Introduction to Computer"]', '["history", "abacus"]', true),
  (sid, caw_id, 'mcq', 'The Pascaline mechanical calculator, invented by Blaise Pascal, is also commonly known as the:', '[{"key": "A", "value": "abacus", "correct": false}, {"key": "B", "value": "adding machine", "correct": true}, {"key": "C", "value": "division machine", "correct": false}, {"key": "D", "value": "difference machine", "correct": false}]', 'B', 2, 'medium', '["Introduction to Computer"]', '["history", "pascaline"]', true),
  (sid, caw_id, 'mcq', 'Who is widely recognized historically as the ''Father of Computer''?', '[{"key": "A", "value": "Dennis Ritchie", "correct": false}, {"key": "B", "value": "John Napier", "correct": false}, {"key": "C", "value": "Charles Babbage", "correct": true}, {"key": "D", "value": "Alan Turing", "correct": false}]', 'C', 2, 'easy', '["Introduction to Computer"]', '["history", "charles_babbage"]', true),
  (sid, caw_id, 'mcq', 'The Analytical Engine, which laid the conceptual framework for modern general-purpose digital computers, was designed by:', '[{"key": "A", "value": "Blaise Pascal", "correct": false}, {"key": "B", "value": "Charles Babbage", "correct": true}, {"key": "C", "value": "Dennis Ritchie", "correct": false}, {"key": "D", "value": "Alan Turing", "correct": false}]', 'B', 2, 'easy', '["Introduction to Computer"]', '["history", "babbage"]', true),
  (sid, caw_id, 'mcq', 'Who designed the first high-speed electronic general-purpose computer, the ENIAC?', '[{"key": "A", "value": "John Von Neumann", "correct": false}, {"key": "B", "value": "Joseph M Jacquard", "correct": false}, {"key": "C", "value": "J. Presper Eckert and John W. Mauchly", "correct": true}, {"key": "D", "value": "All of the above", "correct": false}]', 'C', 2, 'medium', '["Introduction to Computer"]', '["history", "eniac"]', true),
  (sid, caw_id, 'mcq', 'Which was the first computer that provided storage capacity for both instructions and data in its memory?', '[{"key": "A", "value": "EDSAC", "correct": true}, {"key": "B", "value": "EDVAC", "correct": false}, {"key": "C", "value": "ENIAC", "correct": false}, {"key": "D", "value": "UNIVAC", "correct": false}]', 'A', 2, 'medium', '["Introduction to Computer"]', '["history", "edsac"]', true),
  (sid, caw_id, 'mcq', 'Name the first commercially produced general-purpose electronic computer:', '[{"key": "A", "value": "ADVAC", "correct": false}, {"key": "B", "value": "ADSAC", "correct": false}, {"key": "C", "value": "UNIVAC", "correct": true}, {"key": "D", "value": "EDVAC", "correct": false}, {"key": "E", "value": "None of these", "correct": false}]', 'C', 2, 'medium', '["Introduction to Computer"]', '["history", "univac"]', true),
  (sid, caw_id, 'mcq', 'First-generation computers (1940-1956) were based on which of the following switching technologies?', '[{"key": "A", "value": "transistors", "correct": false}, {"key": "B", "value": "conductors", "correct": false}, {"key": "C", "value": "integrated circuits", "correct": false}, {"key": "D", "value": "vacuum tubes", "correct": true}]', 'D', 2, 'easy', '["Introduction to Computer"]', '["generations", "hardware"]', true),
  (sid, caw_id, 'mcq', 'First-generation computers were programmed using which of the following programming languages?', '[{"key": "A", "value": "machine language", "correct": true}, {"key": "B", "value": "assembly language", "correct": false}, {"key": "C", "value": "high-level language", "correct": false}, {"key": "D", "value": "compiler language", "correct": false}]', 'A', 2, 'easy', '["Introduction to Computer"]', '["generations", "languages"]', true),
  (sid, caw_id, 'mcq', 'Which switching device was used in the second generation of computers (1956-1963)?', '[{"key": "A", "value": "Vacuum tubes", "correct": false}, {"key": "B", "value": "Transistors", "correct": true}, {"key": "C", "value": "Integrated Circuits", "correct": false}, {"key": "D", "value": "Microprocessors", "correct": false}]', 'B', 2, 'easy', '["Introduction to Computer"]', '["generations", "hardware"]', true),
  (sid, caw_id, 'mcq', 'Third-generation computers (1964-1971) were manufactured using which of the following core technologies?', '[{"key": "A", "value": "vacuum tubes", "correct": false}, {"key": "B", "value": "transistors", "correct": false}, {"key": "C", "value": "integrated circuits (ICs)", "correct": true}, {"key": "D", "value": "microprocessors", "correct": false}, {"key": "E", "value": "discrete components", "correct": false}]', 'C', 2, 'easy', '["Introduction to Computer"]', '["generations", "hardware"]', true),
  (sid, caw_id, 'mcq', 'An integrated circuit (IC) or silicon chip used in computer systems is commonly nicknamed a:', '[{"key": "A", "value": "transistor", "correct": false}, {"key": "B", "value": "resistor", "correct": false}, {"key": "C", "value": "chip", "correct": true}, {"key": "D", "value": "semiconductor", "correct": false}, {"key": "E", "value": "None of these", "correct": false}]', 'C', 2, 'easy', '["Introduction to Computer"]', '["hardware", "terminology"]', true),
  (sid, caw_id, 'mcq', 'Integrated circuits (ICs) or computer chips are typically manufactured using which of the following materials?', '[{"key": "A", "value": "copper", "correct": false}, {"key": "B", "value": "aluminium", "correct": false}, {"key": "C", "value": "gold", "correct": false}, {"key": "D", "value": "silicon", "correct": true}, {"key": "E", "value": "silver", "correct": false}]', 'D', 2, 'easy', '["Introduction to Computer"]', '["hardware", "materials"]', true),
  (sid, caw_id, 'mcq', 'Personal computers (PCs) are considered fourth-generation systems and contain which of the following main components?', '[{"key": "A", "value": "information", "correct": false}, {"key": "B", "value": "data", "correct": false}, {"key": "C", "value": "vacuum tubes", "correct": false}, {"key": "D", "value": "microprocessors", "correct": true}, {"key": "E", "value": "transistors", "correct": false}]', 'D', 2, 'easy', '["Introduction to Computer"]', '["generations", "hardware"]', true),
  (sid, caw_id, 'mcq', 'What was the name of the first computer developed indigenously in India?', '[{"key": "A", "value": "PARAM", "correct": false}, {"key": "B", "value": "Siddhartha", "correct": true}, {"key": "C", "value": "IBM-370", "correct": false}, {"key": "D", "value": "CRAY-1", "correct": false}]', 'B', 2, 'easy', '["Introduction to Computer"]', '["india", "history"]', true),
  (sid, caw_id, 'mcq', 'The foundational logical architecture of the modern digital computer was developed by which mathematician?', '[{"key": "A", "value": "John Von Neumann", "correct": true}, {"key": "B", "value": "Charles Babbage", "correct": false}, {"key": "C", "value": "Blaise Pascal", "correct": false}, {"key": "D", "value": "Jordan Murn", "correct": false}]', 'A', 2, 'medium', '["Introduction to Computer"]', '["history", "john_von_neumann"]', true),
  (sid, caw_id, 'mcq', 'Who developed the first integrated circuit (IC) chip in 1958?', '[{"key": "A", "value": "Robert Nayak", "correct": false}, {"key": "B", "value": "Charles Babbage", "correct": false}, {"key": "C", "value": "J. S. Kilby", "correct": true}, {"key": "D", "value": "C. V. Raman", "correct": false}]', 'C', 2, 'medium', '["Introduction to Computer"]', '["history", "hardware"]', true),
  (sid, caw_id, 'mcq', 'Computers that are highly portable, lightweight, and convenient for users who travel are known as:', '[{"key": "A", "value": "supercomputers", "correct": false}, {"key": "B", "value": "minicomputers", "correct": false}, {"key": "C", "value": "mainframe computers", "correct": false}, {"key": "D", "value": "laptops", "correct": true}]', 'D', 2, 'easy', '["Introduction to Computer"]', '["classifications", "hardware"]', true),
  (sid, caw_id, 'mcq', 'Users generally apply which of the following devices to access a large centralized mainframe or supercomputer?', '[{"key": "A", "value": "terminal", "correct": true}, {"key": "B", "value": "node", "correct": false}, {"key": "C", "value": "desktop", "correct": false}, {"key": "D", "value": "handheld", "correct": false}]', 'A', 2, 'medium', '["Introduction to Computer"]', '["hardware", "networking"]', true),
  (sid, caw_id, 'mcq', 'What is the name of the first supercomputer developed in India by C-DAC?', '[{"key": "A", "value": "PARAM", "correct": true}, {"key": "B", "value": "CRAY-1", "correct": false}, {"key": "C", "value": "PARAM ISHAN", "correct": false}, {"key": "D", "value": "EPRAM", "correct": false}]', 'A', 2, 'easy', '["Introduction to Computer"]', '["india", "supercomputers"]', true),
  (sid, caw_id, 'mcq', 'A hybrid computer is structurally defined as having the combined operational properties of which two computers?', '[{"key": "A", "value": "super and microcomputers", "correct": false}, {"key": "B", "value": "mini and microcomputers", "correct": false}, {"key": "C", "value": "analog and digital computers", "correct": true}, {"key": "D", "value": "super and mini computers", "correct": false}, {"key": "E", "value": "None of the above", "correct": false}]', 'C', 2, 'medium', '["Introduction to Computer"]', '["classifications", "hybrid"]', true),
  (sid, caw_id, 'mcq', 'Which of the following types of computers are used in hospitals to control sensitive medical monitoring machines like ECG and Dialysis?', '[{"key": "A", "value": "Digital", "correct": false}, {"key": "B", "value": "Hybrid", "correct": true}, {"key": "C", "value": "Analog", "correct": false}, {"key": "D", "value": "Microcomputer", "correct": false}]', 'B', 2, 'medium', '["Introduction to Computer"]', '["classifications", "applications"]', true),
  (sid, caw_id, 'mcq', 'Which branch of computer science attempts to produce systems that display the same type of cognitive intelligence that humans do?', '[{"key": "A", "value": "Nano science", "correct": false}, {"key": "B", "value": "Nano technology", "correct": false}, {"key": "C", "value": "Simulation", "correct": false}, {"key": "D", "value": "Artificial Intelligence (AI)", "correct": true}]', 'D', 2, 'easy', '["Introduction to Computer"]', '["ai", "terminology"]', true),
  (sid, caw_id, 'mcq', 'The first formal computer architecture model was introduced in which year?', '[{"key": "A", "value": "1970", "correct": true}, {"key": "B", "value": "1968", "correct": false}, {"key": "C", "value": "1971", "correct": false}, {"key": "D", "value": "1973", "correct": false}]', 'A', 2, 'hard', '["Computer Architecture"]', '["history", "fundamentals"]', true),
  (sid, caw_id, 'mcq', 'Which of the following is the metal or plastic chassis/case that holds all the physical parts of the computer?', '[{"key": "A", "value": "System unit", "correct": true}, {"key": "B", "value": "CPU", "correct": false}, {"key": "C", "value": "Mainframe", "correct": false}, {"key": "D", "value": "Platform", "correct": false}, {"key": "E", "value": "Microprocessor", "correct": false}]', 'A', 2, 'easy', '["Computer Architecture"]', '["hardware", "system_unit"]', true),
  (sid, caw_id, 'mcq', 'Which component is widely known as the ''brain'' of the computer, responsible for processing data?', '[{"key": "A", "value": "Keyboard", "correct": false}, {"key": "B", "value": "Mouse", "correct": false}, {"key": "C", "value": "CPU", "correct": true}, {"key": "D", "value": "Printer", "correct": false}]', 'C', 2, 'easy', '["Computer Architecture"]', '["cpu", "hardware"]', true),
  (sid, caw_id, 'mcq', 'The Central Processing Unit (CPU) consists of which of the following three main units?', '[{"key": "A", "value": "input, output and processing", "correct": false}, {"key": "B", "value": "control unit, primary storage and secondary storage", "correct": false}, {"key": "C", "value": "control unit, arithmetic logic unit, memory unit", "correct": true}, {"key": "D", "value": "All of the above", "correct": false}]', 'C', 2, 'medium', '["Computer Architecture"]', '["cpu", "structure"]', true),
  (sid, caw_id, 'mcq', 'In the computing domain, what does the abbreviation ''ALU'' stand for?', '[{"key": "A", "value": "Application and Logic Unit", "correct": false}, {"key": "B", "value": "Algorithm Logic Unit", "correct": false}, {"key": "C", "value": "Arithmetic Layered Unit", "correct": false}, {"key": "D", "value": "Arithmetic Legal Unit", "correct": false}, {"key": "E", "value": "Arithmetic Logic Unit", "correct": true}]', 'E', 2, 'easy', '["Computer Architecture"]', '["cpu", "alu", "terminology"]', true),
  (sid, caw_id, 'mcq', 'Which small, extremely high-speed storage location is embedded directly within the computer processor to hold intermediate execution data or instructions?', '[{"key": "A", "value": "Register", "correct": true}, {"key": "B", "value": "WAN", "correct": false}, {"key": "C", "value": "Bus", "correct": false}, {"key": "D", "value": "Address", "correct": false}, {"key": "E", "value": "Processor", "correct": false}]', 'A', 2, 'medium', '["Computer Architecture"]', '["cpu", "registers"]', true),
  (sid, caw_id, 'mcq', 'The portion of the CPU that directs and coordinates the activities of all the other computer components is the:', '[{"key": "A", "value": "motherboard", "correct": false}, {"key": "B", "value": "coordination board", "correct": false}, {"key": "C", "value": "control unit", "correct": true}, {"key": "D", "value": "arithmetic logic unit", "correct": false}, {"key": "E", "value": "None of these", "correct": false}]', 'C', 2, 'medium', '["Computer Architecture"]', '["cpu", "control_unit"]', true),
  (sid, caw_id, 'mcq', 'Because of its role in regulating signals and data flow, the Control Unit of a digital computer is often called the:', '[{"key": "A", "value": "clock", "correct": false}, {"key": "B", "value": "nerve centre", "correct": true}, {"key": "C", "value": "Both ''1'' and ''2''", "correct": false}, {"key": "D", "value": "IC", "correct": false}]', 'B', 2, 'medium', '["Computer Architecture"]', '["cpu", "control_unit"]', true),
  (sid, caw_id, 'mcq', 'Who invented the world''s first single-chip commercial microprocessor, the Intel 4004?', '[{"key": "A", "value": "Vint Cerf", "correct": false}, {"key": "B", "value": "Terence Percival", "correct": false}, {"key": "C", "value": "John Mauchly", "correct": false}, {"key": "D", "value": "Ted Hoff", "correct": true}]', 'D', 2, 'hard', '["Computer Architecture"]', '["history", "microprocessor"]', true),
  (sid, caw_id, 'mcq', 'The main electronic circuit board in the computer that connects and facilitates communication between all hardware parts is the:', '[{"key": "A", "value": "bus", "correct": false}, {"key": "B", "value": "line", "correct": false}, {"key": "C", "value": "media", "correct": false}, {"key": "D", "value": "motherboard", "correct": true}, {"key": "E", "value": "None of these", "correct": false}]', 'D', 2, 'easy', '["Computer Architecture"]', '["motherboard", "hardware"]', true),
  (sid, caw_id, 'mcq', 'The exact location address of an I/O device or specific memory slot is carried through the motherboard by the:', '[{"key": "A", "value": "data bus", "correct": false}, {"key": "B", "value": "expansion bus", "correct": false}, {"key": "C", "value": "address bus", "correct": true}, {"key": "D", "value": "system bus", "correct": false}]', 'C', 2, 'medium', '["Computer Architecture"]', '["motherboard", "buses"]', true),
  (sid, caw_id, 'mcq', 'A device that provides surge protection and furnishes a computer with battery backup power during a main electrical blackout is a(n):', '[{"key": "A", "value": "Battery strip", "correct": false}, {"key": "B", "value": "UPS", "correct": true}, {"key": "C", "value": "Surge strip", "correct": false}, {"key": "D", "value": "USB", "correct": false}, {"key": "E", "value": "Memory", "correct": false}]', 'B', 2, 'easy', '["Computer Architecture"]', '["hardware", "power"]', true),
  (sid, caw_id, 'mcq', 'What is the full form of the computing acronym ''DMA''?', '[{"key": "A", "value": "Direct Memory Access", "correct": true}, {"key": "B", "value": "Dynamic Memory Access", "correct": false}, {"key": "C", "value": "Direct Method Access", "correct": false}, {"key": "D", "value": "Double Memory Access", "correct": false}]', 'A', 2, 'medium', '["Computer Architecture"]', '["cpu", "memory", "terminology"]', true),
  (sid, caw_id, 'mcq', 'What are the four active phases contained in a standard computer hardware machine cycle?', '[{"key": "A", "value": "fetch, decode, execute, store", "correct": false}, {"key": "B", "value": "fetch, execute, compile, store", "correct": false}, {"key": "C", "value": "load, run, output, save", "correct": false}, {"key": "D", "value": "fetch, decode, execute, and store", "correct": true}]', 'D', 2, 'medium', '["Computer Architecture"]', '["execution", "machine_cycle"]', true),
  (sid, caw_id, 'mcq', 'In computer systems, the process of carrying out compiled hardware instructions is formally called:', '[{"key": "A", "value": "Fetching", "correct": false}, {"key": "B", "value": "Storing", "correct": false}, {"key": "C", "value": "Decoding", "correct": false}, {"key": "D", "value": "Executing", "correct": true}]', 'D', 2, 'easy', '["Computer Architecture"]', '["execution"]', true),
  (sid, caw_id, 'mcq', 'Any physical, tangible component of a computer system that a user can see and touch is classified as:', '[{"key": "A", "value": "software", "correct": false}, {"key": "B", "value": "peripheral", "correct": false}, {"key": "C", "value": "storage", "correct": false}, {"key": "D", "value": "CPU", "correct": false}, {"key": "E", "value": "hardware", "correct": true}]', 'E', 2, 'easy', '["Computer Hardware"]', '["terminology", "hardware"]', true),
  (sid, caw_id, 'mcq', 'Which of the following categories do the keys Shift, Ctrl, and Alt belong to on a computer keyboard?', '[{"key": "A", "value": "Modifier Keys", "correct": true}, {"key": "B", "value": "Primary Keys", "correct": false}, {"key": "C", "value": "Function Keys", "correct": false}, {"key": "D", "value": "Alternate Keys", "correct": false}, {"key": "E", "value": "Candidate Keys", "correct": false}]', 'A', 2, 'easy', '["Computer Hardware"]', '["keyboard", "hardware"]', true),
  (sid, caw_id, 'mcq', 'Who built the very first prototype of the computer mouse in the 1960s?', '[{"key": "A", "value": "Douglas Engelbart", "correct": true}, {"key": "B", "value": "William English", "correct": false}, {"key": "C", "value": "Daniel Coogher", "correct": false}, {"key": "D", "value": "Robert Zawacki", "correct": false}]', 'A', 2, 'hard', '["Computer Hardware"]', '["history", "hardware"]', true),
  (sid, caw_id, 'mcq', 'Which pointing/input interface is standard for public access devices such as Bank ATMs, hospital kiosks, and airline check-ins?', '[{"key": "A", "value": "Light pen", "correct": false}, {"key": "B", "value": "Touch screen", "correct": true}, {"key": "C", "value": "Joystick", "correct": false}, {"key": "D", "value": "Trackball", "correct": false}]', 'B', 2, 'easy', '["Computer Hardware"]', '["hardware", "interfaces"]', true),
  (sid, caw_id, 'mcq', 'A barcode reader, which is used at retail checkout counters to read product codes, is classified as a(n):', '[{"key": "A", "value": "processing device", "correct": false}, {"key": "B", "value": "storage device", "correct": false}, {"key": "C", "value": "input device", "correct": true}, {"key": "D", "value": "output device", "correct": false}]', 'C', 2, 'easy', '["Computer Hardware"]', '["hardware", "scanners"]', true),
  (sid, caw_id, 'mcq', 'What is the full form of ''MICR'', a technology used primarily by the banking industry to read checks?', '[{"key": "A", "value": "Magnetic Ink Character Recognition", "correct": true}, {"key": "B", "value": "Magnetic Ink Code Reader", "correct": false}, {"key": "C", "value": "Mechanical Ink Character Reader", "correct": false}, {"key": "D", "value": "Modern Ink Code Recognition", "correct": false}]', 'A', 2, 'medium', '["Computer Hardware"]', '["hardware", "scanners", "terminology"]', true),
  (sid, caw_id, 'mcq', 'The physical glass screen of a classic Cathode Ray Tube (CRT) computer monitor is structurally:', '[{"key": "A", "value": "circular", "correct": false}, {"key": "B", "value": "rectangular", "correct": true}, {"key": "C", "value": "eclipse", "correct": false}, {"key": "D", "value": "conical", "correct": false}, {"key": "E", "value": "None of these", "correct": false}]', 'B', 2, 'medium', '["Computer Hardware"]', '["hardware", "monitors"]', true),
  (sid, caw_id, 'mcq', 'What is the standard unit used to measure the printing speed of high-speed modern laser or page printers?', '[{"key": "A", "value": "CPM (Characters Per Minute)", "correct": false}, {"key": "B", "value": "DPI (Dots Per Inch)", "correct": false}, {"key": "C", "value": "PPM (Pages Per Minute)", "correct": true}, {"key": "D", "value": "BIT (Binary Digit)", "correct": false}, {"key": "E", "value": "None of these", "correct": false}]', 'C', 2, 'easy', '["Computer Hardware"]', '["hardware", "printers"]', true),
