  (sid, caw_id, 'mcq', 'If a computer system unexpectedly enters an infinite loop of rebooting itself, it is highly likely that:', '[{"key": "A", "value": "it has been infected with a virus", "correct": true}, {"key": "B", "value": "it does not have enough physical RAM memory", "correct": false}, {"key": "C", "value": "there is no printer connected to the port", "correct": false}, {"key": "D", "value": "there has been a sudden power surge", "correct": false}, {"key": "E", "value": "it needs a CD-ROM drive installed", "correct": false}]', 'A', 2, 'medium', '["Computer Security"]', '["security", "malware"]', true),
  (sid, caw_id, 'mcq', 'What is the primary operational difference between a computer worm and a computer virus?', '[{"key": "A", "value": "A worm infects hardware components directly", "correct": false}, {"key": "B", "value": "A worm is self-replicating and spreads across networks without needing to attach to a host file", "correct": true}, {"key": "C", "value": "A worm requires active human intervention to copy itself", "correct": false}, {"key": "D", "value": "A worm is harmless and does not carry payloads", "correct": false}]', 'B', 2, 'medium', '["Computer Security"]', '["security", "malware"]', true),
  (sid, caw_id, 'mcq', 'A malicious program designed to masquerade and trick a user into downloading it by pretending to be a useful application is called a:', '[{"key": "A", "value": "Trojan horse", "correct": true}, {"key": "B", "value": "Keylogger", "correct": false}, {"key": "C", "value": "Worm", "correct": false}, {"key": "D", "value": "Cracker", "correct": false}]', 'A', 2, 'easy', '["Computer Security"]', '["security", "malware"]', true),
  (sid, caw_id, 'mcq', 'What is the term for a hacking technique where an unauthorized user gains entry to a network by pretending to be a legitimate, trusted computer?', '[{"key": "A", "value": "spoofing", "correct": false}, {"key": "B", "value": "forging", "correct": false}, {"key": "C", "value": "IP spoofing", "correct": true}, {"key": "D", "value": "All of these", "correct": false}]', 'C', 2, 'medium', '["Computer Security"]', '["hacking", "techniques"]', true),
  (sid, caw_id, 'mcq', 'What is the term for sending fraudulent e-mails or creating fake web pages designed to trick individuals into revealing sensitive financial or login passwords?', '[{"key": "A", "value": "Phishing scams", "correct": true}, {"key": "B", "value": "Spam mail", "correct": false}, {"key": "C", "value": "Hacking attacks", "correct": false}, {"key": "D", "value": "Cracking software", "correct": false}]', 'A', 2, 'easy', '["Computer Security"]', '["security", "phishing"]', true),
  (sid, caw_id, 'mcq', 'Unsolicited bulk e-mails sent to a large number of recipients over the Internet are commonly called:', '[{"key": "A", "value": "spam", "correct": true}, {"key": "B", "value": "spoof", "correct": false}, {"key": "C", "value": "sniffer scripts", "correct": false}, {"key": "D", "value": "spool", "correct": false}, {"key": "E", "value": "None of these", "correct": false}]', 'A', 2, 'easy', '["Computer Security"]', '["internet", "security"]', true),
